import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import { expect, userEvent, waitFor, within } from "storybook/test";

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

/**
 * A vertically stacked list of interactive headings that can be individually
 * revealed and hidden to expose content. Supports Basic and Border variants.
 */
const meta = {
  title: "Component/Accordion",
  component: Accordion,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
  },
  argTypes: {
    type: {
      control: "radio",
      description: "Type of accordion behavior",
      options: ["single", "multiple"],
    },
    collapsible: {
      control: "boolean",
      description: "Can an open accordion be collapsed using the trigger",
      if: { arg: "type", eq: "single" },
    },
    variant: {
      control: "radio",
      description: "Visual style variant",
      options: ["basic", "border"],
    },
    defaultValue: {
      control: "radio",
      description: "Initially expanded item (single type)",
      options: ["", "item-1", "item-2", "item-3"],
      if: { arg: "type", eq: "single" },
    },
    disabledItem: {
      control: "radio",
      description: "Which item is disabled",
      options: ["none", "item-1", "item-2", "item-3"],
    },
    trigger1: { control: "text", description: "Item 1 trigger text" },
    trigger2: { control: "text", description: "Item 2 trigger text" },
    trigger3: { control: "text", description: "Item 3 trigger text" },
  },
  args: {
    type: "single",
    collapsible: true,
    variant: "basic",
    defaultValue: "",
    disabledItem: "none",
    trigger1: "How do I reset my password?",
    trigger2: "Can I change my subscription plan?",
    trigger3: "What payment methods do you accept?",
  },
  decorators: [
    (Story) => (
      <div className="w-[480px]">
        <Story />
      </div>
    ),
  ],
  render: (args: AccordionArgs) => {
    const itemClass = args.variant === "border" ? "px-4" : undefined;
    const type = args.type ?? "single";
    const accordionProps =
      type === "single"
        ? {
            type: "single" as const,
            collapsible: args.collapsible ?? true,
            ...(args.defaultValue ? { defaultValue: args.defaultValue } : {}),
          }
        : { type: "multiple" as const };
    const accordion = (
      <Accordion {...accordionProps}>
        <AccordionItem value="item-1" className={itemClass} disabled={args.disabledItem === "item-1"}>
          <AccordionTrigger>{args.trigger1 ?? "How do I reset my password?"}</AccordionTrigger>
          <AccordionContent>
            Click on &apos;Forgot Password&apos; on the login page, enter your
            email address, and we&apos;ll send you a link to reset your password.
            The link will expire in 24 hours.
          </AccordionContent>
        </AccordionItem>
        <AccordionItem value="item-2" className={itemClass} disabled={args.disabledItem === "item-2"}>
          <AccordionTrigger>{args.trigger2 ?? "Can I change my subscription plan?"}</AccordionTrigger>
          <AccordionContent>
            Yes. You can upgrade or downgrade your plan at any time from the
            account settings. Changes take effect at the start of your next
            billing cycle.
          </AccordionContent>
        </AccordionItem>
        <AccordionItem value="item-3" className={itemClass} disabled={args.disabledItem === "item-3"}>
          <AccordionTrigger>{args.trigger3 ?? "What payment methods do you accept?"}</AccordionTrigger>
          <AccordionContent>
            We accept all major credit cards (Visa, Mastercard, American Express),
            PayPal, and bank transfers for annual plans.
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    );
    return args.variant === "border" ? (
      <div className="w-[480px] overflow-hidden rounded-lg border border-border">
        {accordion}
      </div>
    ) : (
      accordion
    );
  },
} as Meta<typeof Accordion>;

export default meta;

type AccordionArgs = {
  type?: "single" | "multiple";
  collapsible?: boolean;
  variant?: "basic" | "border";
  defaultValue?: "" | "item-1" | "item-2" | "item-3";
  disabledItem?: "none" | "item-1" | "item-2" | "item-3";
  trigger1?: string;
  trigger2?: string;
  trigger3?: string;
};

type Story = Omit<StoryObj<typeof meta>, "args"> & { args?: AccordionArgs };

/** 기본 FAQ 스타일. Variant, State, Trigger Text 등 Controls에서 조절 가능. */
export const Default: Story = {};

/** Border variant. 전체 테두리와 둥근 모서리가 있는 카드형 스타일. */
export const Border: Story = {
  args: { variant: "border" },
  render: (args: AccordionArgs) => {
    const type = args.type ?? "single";
    const accordionProps =
      type === "single"
        ? {
            type: "single" as const,
            collapsible: args.collapsible ?? true,
            ...(args.defaultValue ? { defaultValue: args.defaultValue } : {}),
          }
        : { type: "multiple" as const };
    return (
    <div className="w-[480px] overflow-hidden rounded-lg border border-border">
      <Accordion {...accordionProps}>
        <AccordionItem value="item-1" className="px-4">
          <AccordionTrigger>How does billing work?</AccordionTrigger>
          <AccordionContent>
            We offer monthly and annual subscription plans. Billing is charged
            at the beginning of each cycle, and you can cancel anytime. All
            plans include automatic backups, 24/7 support, and unlimited team
            members.
          </AccordionContent>
        </AccordionItem>
        <AccordionItem value="item-2" className="px-4">
          <AccordionTrigger>Is my data secure?</AccordionTrigger>
          <AccordionContent>
            Yes. We use industry-standard encryption (AES-256) for data at rest
            and TLS 1.3 for data in transit. We are SOC 2 Type II certified.
          </AccordionContent>
        </AccordionItem>
        <AccordionItem value="item-3" className="px-4">
          <AccordionTrigger>What integrations do you support?</AccordionTrigger>
          <AccordionContent>
            We integrate with Slack, Jira, GitHub, Google Workspace, and
            Microsoft 365. More integrations are available via our API.
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    </div>
    );
  },
};

/** 섹션 헤더가 있는 카드형 FAQ. Subscription & Billing 예시. */
export const SubscriptionAndBilling: Story = {
  render: (args: AccordionArgs) => {
    const type = args.type ?? "single";
    const accordionProps =
      type === "single"
        ? {
            type: "single" as const,
            collapsible: args.collapsible ?? true,
            ...(args.defaultValue ? { defaultValue: args.defaultValue } : {}),
          }
        : { type: "multiple" as const };
    return (
    <Card className="w-[480px]">
      <CardHeader className="flex flex-col gap-1">
        <CardTitle>Subscription & Billing</CardTitle>
        <CardDescription>
          Common questions about your account, plans, payments and cancellations.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Accordion {...accordionProps}>
          <AccordionItem value="item-1">
            <AccordionTrigger>What subscription plans do you offer?</AccordionTrigger>
            <AccordionContent>
              We offer three subscription tiers: Starter ($9/month),
              Professional ($29/month), and Enterprise ($99/month). Each plan
              includes increasing storage limits, API access, priority support,
              and team collaboration features.
            </AccordionContent>
          </AccordionItem>
          <AccordionItem value="item-2">
            <AccordionTrigger>Can I change my subscription plan?</AccordionTrigger>
            <AccordionContent>
              Yes. You can upgrade or downgrade at any time. Changes take effect
              at the start of your next billing cycle.
            </AccordionContent>
          </AccordionItem>
          <AccordionItem value="item-3">
            <AccordionTrigger>What payment methods do you accept?</AccordionTrigger>
            <AccordionContent>
              We accept all major credit cards, PayPal, and bank transfers for
              annual plans.
            </AccordionContent>
          </AccordionItem>
        </Accordion>
      </CardContent>
    </Card>
    );
  },
};

/** 비활성화된 아이템이 포함된 예시. (Default에서 disabledItem 컨트롤로 동일 설정 가능) */
export const WithDisabled: Story = {
  args: { disabledItem: "item-2" },
};

/** 여러 아이템을 동시에 열 수 있는 multiple 타입. */
export const Multiple: Story = {
  args: {
    type: "multiple",
  },
};

export const ShouldOnlyOpenOneWhenSingleType: Story = {
  name: "when accordions are clicked, should open only one item at a time",
  args: {
    type: "single" as const,
  },
  tags: ["!dev", "!autodocs"],
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const accordions = await canvas.getAllByRole("button");

    for (const trigger of accordions) {
      await userEvent.click(trigger);
      await waitFor(async () => {
        const content = await canvas.findAllByRole("region");
        return expect(content.length).toBe(1);
      });
    }

    await userEvent.click(accordions[accordions.length - 1]);
    await waitFor(async () => {
      const content = await canvas.queryByRole("region");
      return expect(content).toBeFalsy();
    });
  },
};

export const ShouldOpenAllWhenMultipleType: Story = {
  name: "when accordions are clicked, should open all items one at a time",
  args: {
    type: "multiple",
  },
  tags: ["!dev", "!autodocs"],
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const accordions = await canvas.getAllByRole("button");

    for (let i = 0; i < accordions.length; i++) {
      await userEvent.click(accordions[i]);
      await waitFor(async () => {
        const content = await canvas.findAllByRole("region");
        return expect(content.length).toBe(i + 1);
      });
    }

    for (let i = accordions.length - 1; i > 0; i--) {
      await userEvent.click(accordions[i]);
      await waitFor(async () => {
        const content = await canvas.findAllByRole("region");
        return expect(content.length).toBe(i);
      });
    }

    await userEvent.click(accordions[0]);
    await waitFor(async () => {
      const content = await canvas.queryByRole("region");
      return expect(content).toBeFalsy();
    });
  },
};

import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import {
  CircleAlert,
  CircleCheck,
  Info as InfoIcon,
  TriangleAlert,
} from "lucide-react";

import {
  Alert,
  AlertAction,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

/**
 * Displays a callout for user attention.
 */
const meta = {
  title: "Component/Alert",
  component: Alert,
  tags: ["autodocs"],
  argTypes: {
    variant: {
      options: ["default", "destructive", "warning"],
      control: { type: "radio" },
    },
  },
  args: {
    variant: "default",
  },
  render: (args) => (
    <Alert {...args}>
      <AlertTitle>Heads up!</AlertTitle>
      <AlertDescription>
        You can add components to your app using the cli.
      </AlertDescription>
    </Alert>
  ),
} satisfies Meta<typeof Alert>;

export default meta;

type Story = StoryObj<typeof meta>;

/** Default alert with icon, title and description. */
export const Default: Story = {
  render: (args) => (
    <Alert {...args}>
      <CircleAlert className="size-4" />
      <AlertTitle>Success! Your changes have been saved.</AlertTitle>
      <AlertDescription>
        This is an alert with icon, title and description.
      </AlertDescription>
    </Alert>
  ),
};

/** Icon and description only. No title. */
export const IconAndDescription: Story = {
  render: (args) => (
    <Alert {...args}>
      <CircleAlert className="size-4" />
      <AlertDescription>
        This one has an icon and a description only. No title.
      </AlertDescription>
    </Alert>
  ),
};

/** Description only. No title. No icon. */
export const DescriptionOnly: Story = {
  render: (args) => (
    <Alert {...args}>
      <AlertDescription>
        This one has a description only. No title. No icon.
      </AlertDescription>
    </Alert>
  ),
};

/** Icon and title only. No description. */
export const IconAndTitle: Story = {
  render: (args) => (
    <Alert {...args}>
      <CircleAlert className="size-4" />
      <AlertTitle>Let&apos;s try one with icon and title.</AlertTitle>
    </Alert>
  ),
};

/** Long title truncation. */
export const LongTitle: Story = {
  render: (args) => (
    <Alert {...args}>
      <CircleAlert className="size-4" />
      <AlertTitle>
        This is a very long alert title that demonstrates how the component
        handles...
      </AlertTitle>
    </Alert>
  ),
};

/** Long description wrapping. */
export const LongDescription: Story = {
  render: (args) => (
    <Alert {...args}>
      <CircleAlert className="size-4" />
      <AlertDescription>
        This is a very long alert description that demonstrates how the
        component handles extended text content and potentially wraps across
        multiple lines
      </AlertDescription>
    </Alert>
  ),
};

/** Destructive alert for errors. */
export const Destructive: Story = {
  render: (args) => (
    <Alert {...args} variant="destructive">
      <CircleAlert className="size-4" />
      <AlertTitle>Something went wrong!</AlertTitle>
      <AlertDescription>
        Your session has expired. Please log in again.
      </AlertDescription>
    </Alert>
  ),
};

/** Destructive with bullet list. */
export const DestructiveWithList: Story = {
  render: (args) => (
    <Alert {...args} variant="destructive">
      <CircleAlert className="size-4" />
      <AlertTitle>Unable to process your payment.</AlertTitle>
      <AlertDescription>
        <p>Please verify your billing information and try again.</p>
        <ul>
          <li>Check your card details</li>
          <li>Ensure sufficient funds</li>
          <li>Verify billing address</li>
        </ul>
      </AlertDescription>
    </Alert>
  ),
};

/** Alert with Undo action button. */
export const WithUndoAction: Story = {
  render: (args) => (
    <Alert {...args}>
      <CircleAlert className="size-4" />
      <AlertTitle>The selected emails have been marked as spam.</AlertTitle>
      <AlertAction>
        <Button variant="outline" size="sm">
          Undo
        </Button>
      </AlertAction>
    </Alert>
  ),
};

/** Success alert with CircleCheck icon. */
export const Success: Story = {
  render: (args) => (
    <Alert {...args}>
      <CircleCheck className="size-4" />
      <AlertTitle>Payment successful</AlertTitle>
      <AlertDescription>
        Your payment of $29.99 has been processed. A receipt has been sent to
        your email address.
      </AlertDescription>
    </Alert>
  ),
};

/** Info alert with Info icon. */
export const Info: Story = {
  render: (args) => (
    <Alert {...args}>
      <InfoIcon className="size-4" />
      <AlertTitle>New feature available</AlertTitle>
      <AlertDescription>
        We&apos;ve added dark mode support. You can enable it in your account
        settings.
      </AlertDescription>
    </Alert>
  ),
};

/** Alert with Enable action button. */
export const WithEnableAction: Story = {
  render: (args) => (
    <Alert {...args}>
      <AlertTitle>Dark mode is now available</AlertTitle>
      <AlertDescription>
        Enable it under your profile settings to get started.
      </AlertDescription>
      <AlertAction>
        <Button size="sm">Enable</Button>
      </AlertAction>
    </Alert>
  ),
};

/** Warning variant with amber styling. */
export const Warning: Story = {
  render: (args) => (
    <Alert {...args} variant="warning">
      <TriangleAlert className="size-4" />
      <AlertTitle>Your subscription will expire in 3 days.</AlertTitle>
      <AlertDescription>
        Renew now to avoid service interruption or upgrade to a paid plan to
        continue using the service.
      </AlertDescription>
    </Alert>
  ),
};

﻿import type { Meta, StoryObj } from "@storybook/nextjs-vite";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { userEvent, within } from "storybook/test";

/**
 * A modal dialog that interrupts the user with important content and expects
 * a response.
 */
const meta = {
  title: "Component/AlertDialog",
  component: AlertDialog,
  tags: ["autodocs"],
  argTypes: {},
  render: (args) => (
    <AlertDialog {...args}>
      <AlertDialogTrigger>Open</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Are you sure absolutely sure?</AlertDialogTitle>
          <AlertDialogDescription>
            This action cannot be undone. This will permanently delete your
            account and remove your data from our servers.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction>Continue</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  ),
  parameters: {
    layout: "centered",
  },
} satisfies Meta<typeof AlertDialog>;

export default meta;

type Story = StoryObj<typeof meta>;

/**
 * The default form of the alert dialog.
 */
export const Default: Story = {};

export const ShouldOpenClose: Story = {
  name: "when alert dialog trigger is pressed, should open the dialog and be able to close it",
  tags: ["!dev", "!autodocs"],
  play: async ({ canvasElement, canvas, step }) => {
    const canvasBody = within(canvasElement.ownerDocument.body);

    await step("open the alert dialog", async () => {
      await userEvent.click(
        await canvas.getByRole("button", {
          name: /open/i,
        }),
      );
    });

    await step("close the alert dialog", async () => {
      await userEvent.click(
        await canvasBody.getByRole("button", {
          name: /cancel/i,
        }),
        { delay: 100 },
      );
    });
  },
};

