import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
// Replace nextjs-vite with the name of your framework
import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import type { CSSProperties, ReactNode } from "react";

type Typography = {
  name: string;
  value: string;
};

const TypographyRow = ({
  value,
  name,
  styleKey,
  children,
}: {
  value: string;
  name: string;
  styleKey: keyof CSSProperties;
  children?: ReactNode;
}) => {
  const isVar = value.startsWith("--");
  const styleValue = isVar ? `var(${value})` : value;
  const resolved = isVar
    ? getComputedStyle(document.documentElement).getPropertyValue(value) ||
      styleValue
    : value;

  return (
    <TableRow>
      <TableCell>{name}</TableCell>
      <TableCell>
        {String(resolved)
          .split(",")
          .map((v, idx) => (
            <p key={`prop-${idx}`}>{v.trim()}</p>
          ))}
      </TableCell>
      <TableCell>
        <div
          style={{
            [styleKey]: styleValue as CSSProperties[typeof styleKey],
          }}
          className="line-clamp-1"
        >
          {children}
        </div>
      </TableCell>
    </TableRow>
  );
};

/**
 * Typography tokens for the design system.
 */
const meta: Meta<{
  children: string;
  key: keyof CSSProperties;
  property: Typography[];
}> = {
  title: "Token/Typography",
  argTypes: {},
  args: {
    children: "Typeface",
  },
  render: (args) => (
    <Table>
      <TableHeader>
        <TableRow>
          <TableHead>Name</TableHead>
          <TableHead>Property</TableHead>
          <TableHead>
            <span className="sr-only">Preview</span>
          </TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {args.property.map(({ name, value }) => (
          <TypographyRow
            key={name}
            name={name}
            value={value}
            styleKey={args.key}
          >
            {args.children}
          </TypographyRow>
        ))}
      </TableBody>
    </Table>
  ),
};

export default meta;

